\begin{array}{l}
\displaystyle{
\sum_{k=1}^\infty\frac1{k!}
\sum_{i\in P,m\in\mb Z_+}
q_i\otimes(-\partial)^m
\kappa\Big(
a(z)\otimes1\,\Big|\,
\frac{\partial}{\partial q_i^{(m)}}(\ad U(z))^kL(z)
