\sum_{k=1}^\infty\frac1{k!}
} \\
\displaystyle{
\times
\!\sum_{i\in P,m\in\mb Z_+}\!\!
q_i\otimes(-\partial)^m
\kappa\Bigg(
a(z)\otimes1\,\Bigg|\,
\sum_{h=0}^{k-1}
(\ad U(z))^h \big(\ad \frac{\partial U(z)}{\partial q_i^{(m)}}\big) (\ad U(z))^{k-h-1} L(z)
} \\
\displaystyle{
+(\ad U(z))^k\frac{\partial}{\partial q_i^{(m)}}(q+(f+zs)\otimes1)
-(\ad U(z))^{k-1}\frac{\partial U(z)}{\partial q_i^{(m-1)}}
