=
\!\!\!
\sum_{h,k\in\mb Z_+}^\infty
\!\!\!
\frac1{(h\!+\!k\!+\!1)!}
} \\
\displaystyle{
\times\sum_{i\in P,m\in\mb Z_+}
q_i\otimes(-\partial)^m
\kappa\Bigg(
a(z)\otimes1\,\Bigg|\,
(\ad U(z))^h \big(\ad \frac{\partial U(z)}{\partial q_i^{(m)}}\big) (\ad U(z))^k L(z)
\Bigg)
} \\
\displaystyle{
+\sum_{k=1}^\infty\frac1{k!}
(\pi_{\mf p}\otimes1)\left((-\ad U(z))^k (a(z)\otimes1)\right)
} \\
\displaystyle{
-\sum_{k\in\mb Z_+}\frac1{(k+1)!}
\sum_{i\in P,m\in\mb Z_+}
q_i\otimes(-\partial)^m
\kappa\Bigg(
a(z)\otimes1\,\Bigg|\,
(\ad U(z))^{k}\frac{\partial U(z)}{\partial q_i^{(m-1)}}
